import os
import time
from datetime import datetime, timedelta

from taf.sbts.oam.coam.admin import admin
from taf.collectors.core import core
from taf.transport.ssh import ssh
from taf.rfrl.bts.devices.cu.cu_logs_collector import CuLogsCollector
from taf.rfrl.procedures.resources.python.LogCollection import LogCollection as HWPTA_LogCollection
from taf.rfrl.procedures.resources.python.logger import log_warning, log_step, log_result, log_input_and_output
from taf.rfrl.procedures.resources.python.testline.TestLine import TestLine


class StopAndFix:
    def __init__(self):
        self._truck_roll_fault_ids = [10, 1806, 1850, 1911, 2922, 4341, 4352, 4383]
        self._stop_time = 0
        self._logs_path = '/tmp/stop_and_fix_logs'
        self._gnb_config = None
        self._enb_config = None
        self._admin_alias = 'stop_and_fix'
        self._admin_client = admin()
        self._ssh_alias = 'stop_and_fix'
        self._ssh_client = ssh()

    @log_input_and_output
    def stop_and_fix_if_necessary(self, gnb_config, enb_config, stop_time=86400, logs_path=None):
        """
        Stops test execution and collects proper logs if any of the following conditions will be met:
           - either M-plane or LMP cannot be successfully pinged on gNB or eNB,
           - any truck roll alarm will be active on gNB or eNB,
           - any SMOD, BBMOD or RMOD specified in TL config file will not be detected on gNB.

        :param gnb_config: configuration object of gNB BTS which will be checked and from which logs will be collected;
                           should contain all data required to connect to given gNB BTS;
                           should contain M-plane and LMP IP addresses;
                           should contain serial numbers of all expected modules;
                           if None provided then nothing on gNB BTS will be checked and
                           logs from gNB BTS will not be collected;
                           supported gNB BTS configuration class: ClassicalBts.
        :type gnb_config: taf.config.testline.gnb.gnb.gNB or None
        :param enb_config: configuration object of eNB BTS which will be checked and from which logs will be collected;
                           should contain all data required to connect to given eNB BTS;
                           should contain M-plane and LMP IP addresses;
                           if None provided then nothing on eNB BTS will be checked and
                           logs from eNB BTS will not be collected;
                           supported eNB BTS configuration class: RealEnb.
        :type enb_config: taf.config.testline.enb.RealEnb or None
        :param stop_time: time (in seconds) for which test execution will be stopped;
                          defaults to 24 hours.
        :type stop_time: int
        :param logs_path: absolute path of directory to which logs will be collected
                          i.e. '/home/ute/stop_and_fix_logs';
                          defaults to None (default path in /tmp dir will be used).
        :type logs_path: str
        """
        self._stop_time = stop_time
        self._logs_path = logs_path if logs_path is not None else self._logs_path
        self._gnb_config = gnb_config
        self._enb_config = enb_config

        if self._gnb_config:
            self._check_gnb_pings()
            self._check_gnb_alarms()
            self._check_gnb_modules_detection()

        if self._enb_config:
            self._check_enb_pings()
            self._check_enb_alarms()

    @log_input_and_output
    def _check_gnb_pings(self):
        if not self._is_gnb_mplane_pingable():
            self._trigger_stop_and_fix(reason='gNB M-plane could not be pinged successfully.')

        if not self._is_gnb_lmp_pingable():
            self._trigger_stop_and_fix(reason='gNB LMP could not be pinged successfully.')

    @log_input_and_output
    def _is_gnb_mplane_pingable(self):
        gnb_mplane_ip = self._gnb_config.cu.backhaul_site_oam_ip
        return self._is_pingable(gnb_mplane_ip)

    @log_input_and_output
    def _is_gnb_lmp_pingable(self):
        if common_units := self._gnb_config.dus[0].airscale.common_units:
            gnb_lmp_ip = common_units[0].lmp_connection.addr
        else:
            gnb_lmp_ip = self._gnb_config.dus[0].airscale.core_units[0].lmp_connection.addr
        return self._is_pingable(gnb_lmp_ip)

    @log_input_and_output
    def _check_gnb_alarms(self):
        self._connect_to_gnb()
        try:
            current_alarms = self._admin_client.get_active_alarms(connection=self._admin_alias)
        finally:
            self._disconnect_from_gnb()

        self._analyze_current_alarms(current_alarms, 'gNB')

    @log_input_and_output
    def _check_gnb_modules_detection(self):
        detected_gnb_modules = self._get_detected_gnb_modules()
        expected_gnb_modules = self._get_expected_gnb_modules()
        self._analyze_gnb_modules(detected_gnb_modules, expected_gnb_modules)

    def _get_detected_gnb_modules(self):
        self._connect_to_gnb()
        try:
            return self._admin_client.get_bts_info(connection=self._admin_alias)
        finally:
            self._disconnect_from_gnb()

    def _get_expected_gnb_modules(self):
        expected_modules = {'smods': [],
                            'bbmods': [],
                            'rmods': []}

        test_line = TestLine()
        expected_modules['smods'] = test_line.get_smods_configs()
        expected_modules['bbmods'] = test_line.get_bbmods_configs()
        expected_modules['rmods'] = test_line.get_radios_configs()

        return expected_modules

    def _analyze_gnb_modules(self, detected_modules, expected_modules):
        self._analyze_serial_numbers(detected_modules['systemModules'], expected_modules['smods'], 'SMOD')
        self._analyze_serial_numbers(detected_modules['basebandModules'], expected_modules['bbmods'], 'BBMOD')
        self._analyze_serial_numbers(detected_modules['radioModules']['rmod'], expected_modules['rmods'], 'RMOD')

    @log_input_and_output
    def _analyze_serial_numbers(self, detected_modules, expected_modules, module_type):
        detected_serial_numbers = [module['serialNumber'] for module in detected_modules]
        expected_serial_numbers = [module.serial_number for module in expected_modules]

        for expected_serial_number in expected_serial_numbers:
            if expected_serial_number not in detected_serial_numbers:
                self._trigger_stop_and_fix(reason='Expected {} with serial number {} not detected on gNB.'.format(
                    module_type, expected_serial_number))

    @log_input_and_output
    def _check_enb_pings(self):
        if not self._is_enb_mplane_pingable():
            self._trigger_stop_and_fix(reason='eNB M-plane could not be pinged successfully.')

        if not self._is_enb_lmp_pingable():
            self._trigger_stop_and_fix(reason='eNB LMP could not be pinged successfully.')

    @log_input_and_output
    def _is_enb_mplane_pingable(self):
        enb_mplane_ip = self._enb_config.oam_ip.v4 if self._enb_config.oam_ip.v4 else self._enb_config.oam_ip.v6
        return self._is_pingable(enb_mplane_ip)

    @log_input_and_output
    def _is_enb_lmp_pingable(self):
        airscale = self._enb_config.airscale if self._enb_config.airscale else self._enb_config.system_module
        if common_units := airscale.common_units:
            enb_lmp_ip = common_units[0].lmp_connection.addr
        else:
            enb_lmp_ip = airscale.core_units[0].lmp_connection.addr
        self._connect_to_enb_vm()

        try:
            return self._is_pingable(enb_lmp_ip, remotely=True)
        finally:
            self._disconnect_from_enb_vm()

    @log_input_and_output
    def _check_enb_alarms(self):
        self._connect_to_enb()
        try:
            current_alarms = self._admin_client.get_active_alarms(connection=self._admin_alias)
        finally:
            self._disconnect_from_enb()

        self._analyze_current_alarms(current_alarms, 'eNB')

    def _connect_to_gnb(self):
        self._admin_client.connect_to(bts_host=self._gnb_config.cu.oam_http_connection_details.addr,
                                      bts_port=self._gnb_config.cu.oam_http_connection_details.port,
                                      username=self._gnb_config.cu.oam_http_connection_details.username,
                                      password=self._gnb_config.cu.oam_http_connection_details.password,
                                      name=self._admin_alias)

    def _disconnect_from_gnb(self):
        self._admin_client.teardown(connection=self._admin_alias)

    def _connect_to_enb(self):
        try:
            self._admin_client.connect_to(bts_host=self._enb_config.oam_ip.v4,
                                          bts_port=443,
                                          name=self._admin_alias)
        except Exception:
            log_warning('Cannot connect to eNB via M-plane, trying LMP...')
            enb_vm_credentials = TestLine().get_bts_test_pc_credentials(bts_type='ENB', slave=False)
            self._admin_client.setup_admin(remote_host=enb_vm_credentials['host'],
                                           remote_host_username=enb_vm_credentials['user'],
                                           remote_host_password=enb_vm_credentials['password'],
                                           bts_host=self._enb_config.system_module.common_units[0].lmp_connection.addr,
                                           bts_port=443,
                                           name=self._admin_alias)

    def _disconnect_from_enb(self):
        self._admin_client.teardown(connection=self._admin_alias)

    def _connect_to_enb_vm(self):
        enb_vm_credentials = TestLine().get_bts_test_pc_credentials(bts_type='ENB', slave=False)
        self._ssh_client.connect_to(hostname=enb_vm_credentials['host'],
                                    username=enb_vm_credentials['user'],
                                    password=enb_vm_credentials['password'],
                                    alias=self._ssh_alias)

    def _disconnect_from_enb_vm(self):
        self._ssh_client.disconnect(connection=self._ssh_alias)

    @log_input_and_output
    def _is_pingable(self, ip, remotely=False):
        pings_count = 1
        pings_retry = 6
        ping_status = False
        ping_cmd = 'ping -c {} {}'.format(pings_count, ip)

        for _ in range(0, pings_retry):
            if remotely:
                ping_output = self._ssh_client.execute(command=ping_cmd, connection=self._ssh_alias)
            else:
                ping_output = os.popen(cmd=ping_cmd).read()

            ping_status = self._analyze_ping_output(ping_output, pings_count)
            if ping_status:
                return ping_status

            time.sleep(10)

        return ping_status

    @log_input_and_output
    def _analyze_ping_output(self, ping_output, pings_count):
        expected_ping_output = '{} received'.format(pings_count)
        return expected_ping_output in ping_output

    @log_input_and_output
    def _analyze_current_alarms(self, current_alarms, bts_type):
        current_fault_ids = [current_alarm['faultId'] for current_alarm in current_alarms]

        for truck_roll_fault_id in self._truck_roll_fault_ids:
            if truck_roll_fault_id in current_fault_ids:
                self._trigger_stop_and_fix(reason='Alarm with fault ID {} detected on {}. Make sure whether it should '
                                                  'be handled as a truck roll alarm'.format(truck_roll_fault_id,
                                                                                            bts_type))

    def _trigger_stop_and_fix(self, reason):
        log_warning(reason)

        try:
            self._collect_logs(reason)
        finally:
            self._pause_test_execution()

    @log_input_and_output
    def _collect_logs(self, reason):
        log_warning('Collecting stop and fix logs to {} ...'.format(self._logs_path))
        self._save_reason_into_file(reason)

        if self._gnb_config:
            self._collect_gnb_btslog()
            self._collect_gnb_snapshot()
            self._collect_im_snapshot()
            self._collect_cu_logs()
            self._collect_swconfig()
            self._collect_swdlreport()
            self._collect_gnb_scf()

        if self._enb_config:
            self._collect_enb_btslog()
            self._collect_enb_snapshot()
            self._collect_enb_scf()

    def _save_reason_into_file(self, reason):
        try:
            path = self._logs_path + '/reason.log'
            log_step('Saving stop and fix reason into file {}'.format(path))
            self._ensure_path_will_exist(self._logs_path)

            with open(path, 'w') as reason_log_file:
                reason_log_file.write('{}: {}\n'.format(datetime.now(), reason))

        except Exception as error:
            log_result('Error while saving stop and fix reason into file: {}'.format(error))

    def _collect_gnb_snapshot(self):
        try:
            path = self._logs_path + '/gnb_snapshot'
            log_step('Collecting gNB snapshot to {}'.format(path))
            self._ensure_path_will_exist(path)
            self._connect_to_gnb()
            self._admin_client.collect_snapshot(target_file_name=path + '/gnb_snapshot.zip',
                                                connection=self._admin_alias)
            self._disconnect_from_gnb()
        except Exception as error:
            log_result('Error while collecting gNB snapshot: {}'.format(error))

    def _collect_enb_snapshot(self):
        try:
            path = self._logs_path + '/enb_snapshot'
            log_step('Collecting eNB snapshot to {}'.format(path))
            self._ensure_path_will_exist(path)
            self._connect_to_enb()
            self._admin_client.collect_snapshot(target_file_name=path + '/enb_snapshot.zip',
                                                connection=self._admin_alias)
            self._disconnect_from_enb()
        except Exception as error:
            log_result('Error while collecting eNB snapshot: {}'.format(error))

    def _collect_gnb_btslog(self):
        try:
            path = self._logs_path + '/gnb_btslog'
            log_step('Collecting gNB btslog to {}'.format(path))
            self._ensure_path_will_exist(path)
            self._collect_bts_log('btslog_on_testvm', path)
        except Exception as error:
            log_result('Error while collecting gNB btslog: {}'.format(error))

    def _collect_enb_btslog(self):
        try:
            path = self._logs_path + '/enb_btslog'
            log_step('Collecting eNB btslog to {}'.format(path))
            self._ensure_path_will_exist(path)
            self._collect_bts_log('btslog_on_enb_testvm', path)
        except Exception as error:
            log_result('Error while collecting eNB btslog: {}'.format(error))

    @staticmethod
    def _collect_bts_log(btslog_name, path):
        btslog_collector = core()
        btslog_collector.stop_collectors(names=btslog_name)
        btslog_collector.collect_collectors(names=btslog_name, target_dir=path)
        btslog_collector.teardown_collectors(names=btslog_name)

    def _collect_im_snapshot(self):
        try:
            path = self._logs_path + '/im_snapshot'
            log_step('Collecting IM snapshot to {}'.format(path))
            self._ensure_path_will_exist(path)
            self._connect_to_gnb()
            self._admin_client.collect_im_snapshot(target_file_name=path + '/im_snapshot.ims2',
                                                   timeout=300,
                                                   connection=self._admin_alias)
            self._disconnect_from_gnb()
        except Exception as error:
            log_result('Error while collecting IM snapshot: {}'.format(error))

    def _collect_cu_logs(self):
        try:
            path = self._logs_path + '/cu_logs'
            log_step('Collecting CU logs to {}'.format(path))
            self._ensure_path_will_exist(path)
            cu_logs_collector = CuLogsCollector()
            cu_logs_collector.download_snapshot_from_cu(path=path)
        except Exception as error:
            log_result('Error while collecting CU logs: {}'.format(error))

    def _collect_swconfig(self):
        try:
            path = self._logs_path + '/swconfig'
            log_step('Collecting swconfig to {}'.format(path))
            self._ensure_path_will_exist(path)
            log_collector = HWPTA_LogCollection()
            log_collector.save_swconfig(logs_path=path)
        except Exception as error:
            log_result('Error while collecting swconfig: {}'.format(error))

    def _collect_swdlreport(self):
        try:
            path = self._logs_path + '/swdlreport'
            log_step('Collecting swdlreport logs to {}'.format(path))
            self._ensure_path_will_exist(path)
            log_collector = HWPTA_LogCollection()
            log_collector.download_swdlreport(local_path=path)
        except Exception as error:
            log_result('Error while collecting swdlreport: {}'.format(error))

    def _collect_gnb_scf(self):
        try:
            path = self._logs_path + '/gnb_scf'
            log_step('Collecting gNB SCF to {}'.format(path))
            self._ensure_path_will_exist(path)
            self._connect_to_gnb()
            self._admin_client.get_current_scf_file(local_dir_path=path,
                                                    file_name='gnb_scf.xml',
                                                    connection=self._admin_alias)
            self._disconnect_from_gnb()
        except Exception as error:
            log_result('Error while collecting gNB SCF: {}'.format(error))

    def _collect_enb_scf(self):
        try:
            path = self._logs_path + '/enb_scf'
            log_step('Collecting eNB SCF to {}'.format(path))
            self._ensure_path_will_exist(path)
            self._connect_to_enb()
            self._admin_client.get_current_scf_file(local_dir_path=path,
                                                    file_name='enb_scf.xml',
                                                    connection=self._admin_alias)
            self._disconnect_from_enb()
        except Exception as error:
            log_result('Error while collecting eNB SCF: {}'.format(error))

    @staticmethod
    def _ensure_path_will_exist(path):
        if not os.path.exists(path):
            os.makedirs(path)

    @log_input_and_output
    def _pause_test_execution(self):
        pause_start = datetime.now()
        pause_end = pause_start + timedelta(seconds=self._stop_time)
        log_warning('Pausing test execution for {}s stop and fix. '
                    'Pause start: {}, pause end: {}'.format(self._stop_time, pause_start, pause_end))
        time.sleep(self._stop_time)
